Method.Source:
/// <summary>
/// Get item purch unit.
/// First check if there is a default order setting specific for the site or blank site
/// Otherwise get it from the released product
/// </summary>
/// <param name = "_itemId">Item id</param>
/// <param name = "_inventDimId">Inventory dimension Id</param>
/// <returns>Container with item purch unit and the default order setting record if any</returns>
static container METGetPurchUnit(ItemId       _itemId,
                                 InventDimId  _inventDimId)
{
    UnitOfMeasureSymbol purchUnit;

    // search for a site or the default record (site and no site)
    InventItemPurchSetup purchSetup = InventItemPurchSetup::find(_itemId, _inventDimId);

    purchUnit = (purchSetup && purchSetup.METPurchUnit) ? purchSetup.METPurchUnit :
        InventTableModule::find(_itemId, ModuleInventPurchSales::Purch).UnitId;

    return [purchSetup, purchUnit];
}
